#include <stdint.h>

void processPointer(void)
{
   uint32_t dataValue = 0U;
   uint32_t *sourcePtr = &dataValue;

/* Non-compliant: pointer to object type is converted to a different object pointer type */
   uint16_t *narrowPtr = (uint16_t *)sourcePtr;

